selector_to_html = {"a[href=\"#exercise-2\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise 2<a class=\"headerlink\" href=\"#exercise-2\" title=\"Link to this heading\">#</a></h3><p>This solution has a useful approach sentence and identifies both sets. It is\nstill incomplete because it merely states <span class=\"math notranslate nohighlight math-fallback\" data-math-prerendered=\"\" data-tex=\"|U|=9\\cdot10^6\" data-math-display=\"inline\" data-math-speech=\"the absolute value of U equals 9 times 10 to the sixth power\" role=\"math\" aria-label=\"Math: the absolute value of U equals 9 times 10 to the sixth power. Original TeX: |U|=9\\cdot10^6\"><mjx-container class=\"MathJax math-svg\" jax=\"SVG\" overflow=\"overflow\" aria-hidden=\"true\" focusable=\"false\"><svg style=\"vertical-align: -0.566ex;\" xmlns=\"http://www.w3.org/2000/svg\" width=\"2.977ex\" height=\"2.262ex\" role=\"img\" focusable=\"false\" viewBox=\"0 -750 1316 1000\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><g stroke=\"currentColor\" fill=\"currentColor\" stroke-width=\"0\" transform=\"scale(1,-1)\"><g data-mml-node=\"math\"><g data-mml-node=\"mo\"><use data-c=\"7C\" xlink:href=\"#MJX-1-NCM-N-7C\"></use></g><g data-mml-node=\"mi\" transform=\"translate(278,0)\"><use data-c=\"1D448\" xlink:href=\"#MJX-1-NCM-I-1D448\"></use></g><g data-mml-node=\"mo\" transform=\"translate(1038,0)\"><use data-c=\"7C\" xlink:href=\"#MJX-1-NCM-N-7C\"></use></g></g></g><defs><path id=\"MJX-1-NCM-N-7C\" d=\"M139-250C152-250 159-242 159-226L159 726C159 742 152 750 139 750C126 750 119 742 119 726L119-226C119-242 126-250 139-250Z\"></path><path id=\"MJX-1-NCM-I-1D448\" d=\"M642 680C623 680 559 683 540 683C525 683 518 675 518 659C518 650 525 645 539 644C582 644 603 631 603 605C603 599 602 592 600 585L511 232C496 175 467 126 424 84C377 39 325 17 269 17C195 17 152 67 152 141L153 150C153 169 156 191 163 217L259 602C264 623 273 636 286 641C292 643 309 644 338 644C364 644 375 644 375 668C375 678 369 683 358 683L231 680L104 683C88 683 81 674 81 659C81 652 84 647 89 646C99 645 107 644 112 644C143 643 161 641 166 640C171 639 173 636 173 631C173 629 172 622 169 611L74 230C69 211 67 192 67 172C67 57 150-22 265-22C330-22 390 3 445 54C498 102 532 158 548 223L636 574C649 625 677 643 739 644C753 645 760 653 760 668L760 672C757 679 752 683 743 683C724 683 661 680 642 680Z\"></path><path id=\"MJX-1-NCM-N-3D\" d=\"M698 367L80 367C64 367 56 359 56 344C56 329 64 321 80 321L698 321C714 321 722 329 722 344C722 356 711 367 698 367M698 179L80 179C64 179 56 171 56 156C56 141 64 133 80 133L698 133C714 133 722 141 722 156C722 169 711 179 698 179Z\"></path><path id=\"MJX-1-NCM-N-39\" d=\"M116 140C83 140 67 123 67 89C67 14 128-22 207-22C287-22 351 18 398 99C437 166 457 243 457 329C457 456 434 546 388 599C349 644 304 666 253 666C194 666 145 645 106 602C63 557 42 503 42 440C42 379 60 327 96 284C134 238 183 215 242 215C294 215 334 243 361 299L361 286C361 177 342 103 303 63C272 30 239 14 206 14C166 14 137 23 118 42C149 42 165 60 165 91C165 119 144 140 116 140M243 246C204 246 175 266 155 306C144 329 138 374 138 439C138 504 145 548 158 573C180 613 212 633 253 633C294 633 324 608 343 558C354 531 361 485 361 420C361 333 322 246 243 246Z\"></path><path id=\"MJX-1-NCM-N-22C5\" d=\"M192 250C192 279 168 303 139 303C110 303 86 279 86 250C86 221 110 197 139 197C168 197 192 221 192 250Z\"></path><path id=\"MJX-1-NCM-N-31\" d=\"M269 666C228 624 168 603 89 603L89 564C141 564 184 572 217 588L217 82C217 64 213 52 204 47C195 42 170 39 130 39L95 39L95 0C120 2 174 3 257 3C340 3 394 2 419 0L419 39L384 39C343 39 318 42 310 47C302 52 297 64 297 82L297 636C297 660 295 666 269 666Z\"></path><path id=\"MJX-1-NCM-N-30\" d=\"M249-22C390-22 460 92 460 320C460 473 428 575 365 625C330 652 291 666 250 666C109 666 39 551 39 320C39 136 88-22 249-22M361 524C368 489 371 425 371 332C371 240 367 172 360 128C347 48 310 8 249 8C226 8 203 17 182 34C155 57 139 104 132 176C129 201 128 253 128 332C128 419 131 480 136 513C145 568 163 603 191 618C213 630 232 636 249 636C314 636 350 583 361 524Z\"></path><path id=\"MJX-1-NCM-N-36\" d=\"M383 504C416 504 432 521 432 555C432 627 378 666 304 666C221 666 155 627 106 548C63 480 42 403 42 316C42 189 65 100 112 47C152 1 198-22 251-22C312-22 362 1 401 47C438 91 457 144 457 205C457 266 439 318 403 361C365 407 316 431 257 431C205 431 165 402 138 346L138 352C138 465 166 561 226 605C252 624 279 633 306 633C342 633 368 623 385 602C351 602 334 583 334 553C334 525 355 504 383 504M344 340C355 317 361 272 361 206C361 141 356 98 345 76C325 35 294 14 251 14C222 14 200 24 184 44C171 60 162 74 158 85C146 116 140 163 140 227C140 255 144 282 151 308C164 355 201 399 256 399C295 399 325 379 344 340Z\"></path></defs></svg><mjx-break size=\"4\"> </mjx-break><svg style=\"vertical-align: -0.566ex;\" xmlns=\"http://www.w3.org/2000/svg\" width=\"3.52ex\" height=\"2.262ex\" role=\"img\" focusable=\"false\" viewBox=\"0 -750 1555.8 1000\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><g stroke=\"currentColor\" fill=\"currentColor\" stroke-width=\"0\" transform=\"scale(1,-1)\"><g data-mml-node=\"math\"><g data-mml-node=\"mo\"><use data-c=\"3D\" xlink:href=\"#MJX-1-NCM-N-3D\"></use></g><g data-mml-node=\"mn\" transform=\"translate(1055.8,0)\"><use data-c=\"39\" xlink:href=\"#MJX-1-NCM-N-39\"></use></g></g></g></svg><mjx-break size=\"3\"> </mjx-break><svg style=\"vertical-align: -0.566ex;\" xmlns=\"http://www.w3.org/2000/svg\" width=\"4.382ex\" height=\"2.52ex\" role=\"img\" focusable=\"false\" viewBox=\"0 -864 1936.8 1114\" xmlns:xlink=\"http://www.w3.org/1999/xlink\"><g stroke=\"currentColor\" fill=\"currentColor\" stroke-width=\"0\" transform=\"scale(1,-1)\"><g data-mml-node=\"math\"><g data-mml-node=\"mo\"><use data-c=\"22C5\" xlink:href=\"#MJX-1-NCM-N-22C5\"></use></g><g data-mml-node=\"msup\" transform=\"translate(500.2,0)\"><g data-mml-node=\"mn\"><use data-c=\"31\" xlink:href=\"#MJX-1-NCM-N-31\"></use><use data-c=\"30\" xlink:href=\"#MJX-1-NCM-N-30\" transform=\"translate(500,0)\"></use></g><g data-mml-node=\"mn\" transform=\"translate(1033,393.1) scale(0.707)\"><use data-c=\"36\" xlink:href=\"#MJX-1-NCM-N-36\"></use></g></g></g></g></svg></mjx-container></span> without explaining\nwhy the first factor is 9 or what the exponent 6 represents.</p><p>The first incomplete example gives only a formula. The second is much closer\nto complete, but it leaves one important part of its formula unexplained. Both\nshow that the words must account for the whole model, not merely appear\nsomewhere in the solution.</p>","a[href=\"#example-assignment\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Example assignment<a class=\"headerlink\" href=\"#example-assignment\" title=\"Link to this heading\">#</a></h2><h3>Exercise 1: Forming a student council<a class=\"headerlink\" href=\"#exercise-1-forming-a-student-council\" title=\"Link to this heading\">#</a></h3><p><strong>Points:</strong> 10</p><p>A student organization has 10 mathematics majors and 8 computer science\nmajors. It will choose one president, one secretary, and three ordinary\nrepresentatives. No student may hold two positions. The president and\nsecretary must have different majors. The three ordinary-representative\npositions are not distinguished, and those representatives may have either\nmajor. How many councils are possible?</p>","a[href=\"#exercise-1-forming-a-student-council\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise 1: Forming a student council<a class=\"headerlink\" href=\"#exercise-1-forming-a-student-council\" title=\"Link to this heading\">#</a></h3><p><strong>Points:</strong> 10</p><p>A student organization has 10 mathematics majors and 8 computer science\nmajors. It will choose one president, one secretary, and three ordinary\nrepresentatives. No student may hold two positions. The president and\nsecretary must have different majors. The three ordinary-representative\npositions are not distinguished, and those representatives may have either\nmajor. How many councils are possible?</p>","a[href=\"#sample-rubric\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Sample Rubric<a class=\"headerlink\" href=\"#sample-rubric\" title=\"Link to this heading\">#</a></h2><p>Each exercise is graded out of 10 points.</p>","a[href=\"#exercise-2-seven-digit-numbers-with-repetition\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise 2: Seven-digit numbers with repetition<a class=\"headerlink\" href=\"#exercise-2-seven-digit-numbers-with-repetition\" title=\"Link to this heading\">#</a></h3><p><strong>Points:</strong> 10</p><p>How many seven-digit positive integers have at least one repeated digit?\nRecall that a seven-digit integer cannot begin with 0.</p>","a[href=\"#correct-but-incomplete-solutions\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Correct but incomplete solutions<a class=\"headerlink\" href=\"#correct-but-incomplete-solutions\" title=\"Link to this heading\">#</a></h2><p>The calculations and final answers below are correct, but these solutions\nwould not earn full credit.</p>","a[href=\"#full-credit-solutions\"]":"<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Full-credit solutions<a class=\"headerlink\" href=\"#full-credit-solutions\" title=\"Link to this heading\">#</a></h2><p>These solutions include the required words but are intentionally concise.</p>","a[href=\"#exercise-1\"]":"<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Exercise 1<a class=\"headerlink\" href=\"#exercise-1\" title=\"Link to this heading\">#</a></h3><p>This is incomplete because it does not say what is chosen in each phase, what\nthe two officer terms count, or why the two main quantities are multiplied.</p>","a[href=\"#example-homework-write-ups\"]":"<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Example Homework Write-Ups<a class=\"headerlink\" href=\"#example-homework-write-ups\" title=\"Link to this heading\">#</a></h1><p>This page shows what a complete handwritten homework solution should look like.\nThe goal is not a long proof. For each exercise, write at least one sentence\nthat explains your approach, and give word labels to the quantities in your\ncalculation.</p><p>The model solutions are set in larger, handwriting-like type to suggest the\namount of work that you could reasonably write by hand.</p>"}
skip_classes = ["headerlink", "sd-stretched-link", "no-hover-preview"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(`article.bd-article ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,
                onShow(instance) {MathJax.typesetPromise([instance.popper]).then(() => {});},
            });
        };
    };
    console.log("tippy tips loaded!");
};
